import{_ as t,c as n,o as e,ag as s}from"./chunks/framework.Cycwnjj0.js";const r="/assets/select-desired-table-for-adding-columns.DVuUT-Nk.webp",a="/assets/add-column-button.EsA1IznT.webp",d="/assets/add-new-table-column-popup-page.Brp7eSES.webp",u="/assets/reviews-column-added.Bm8iH6OM.webp",w=JSON.parse('{"title":"Add Columns in Product Tables","description":"","frontmatter":{},"headers":[],"relativePath":"guide/product-tables-module/add-columns-in-product-tables.md","filePath":"guide/product-tables-module/add-columns-in-product-tables.md"}'),l={name:"guide/product-tables-module/add-columns-in-product-tables.md"};function i(c,o,g,m,p,h){return e(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="add-columns-in-product-tables" tabindex="-1">Add Columns in Product Tables <a class="header-anchor" href="#add-columns-in-product-tables" aria-label="Permalink to &quot;Add Columns in Product Tables&quot;">​</a></h1><p><strong>Product Table</strong> offers you showcasing <strong>information</strong> on <strong>Amazon Products</strong> according to your needs through <strong>Tables</strong>. This article will guide you through <strong>Adding</strong> as many <strong>Columns</strong> as you wish in <strong>Product Table/s</strong> with AzonPress for <strong>Amazon</strong> products on your <strong>WordPress</strong> website.</p><h2 id="how-to-add-columns-in-product-tables" tabindex="-1">How To Add Columns In Product Tables <a class="header-anchor" href="#how-to-add-columns-in-product-tables" aria-label="Permalink to &quot;How To Add Columns In Product Tables&quot;">​</a></h2><p>To learn how to <strong>Add Columns</strong> to a <strong>Product table</strong> with <strong>AzonPress</strong>, follow the steps with the screenshots below –</p><p>First, go to <strong>Amazon Products</strong> from the <strong>WordPress Sidebar</strong> or <strong>Product Tables</strong> from the <strong>Amazon</strong> dropdown in the top right corner of the <strong>AzonPress Navbar.</strong></p><p>Now, select the desired <strong>Table</strong> where you want to add columns and click on the <strong>Pencil Icon.</strong></p><p>If you do not have any existing <strong>Product Tables</strong>, you can create a new Product Table.</p><p><img src="'+r+'" alt="Select desired table for adding columns"></p><p>Click on the <strong>Add Column</strong> button to add a new column to the table and a pop-up page will appear.</p><p><img src="'+a+'" alt="Add column button"></p><h2 id="customization-of-added-column" tabindex="-1">Customization of Added Column <a class="header-anchor" href="#customization-of-added-column" aria-label="Permalink to &quot;Customization of Added Column&quot;">​</a></h2><p>Here, you will find different options to customize your newly added Column. These are:</p><p><strong>Column Title</strong>: Write the column title into this field so that you can identify this column later.</p><p><strong>Column Type</strong>: Select the column type from the dropdown list. You will find a range of items for your column choose the appropriate one that suits your needs.</p><p><strong>Column Min Width</strong>: Now, set the minimum width of the column. Remember, it&#39;s not mandatory to put a minimum width value in the column because AzonPress can give here a default value for the new column.</p><p><strong>Custom CSS Class</strong>: If you want any <strong>Custom CSS</strong> Class, you can do it in the Custom CSS Class box.</p><p><strong>Header Alignment</strong> and <strong>Content Alignment</strong>: You can adjust the alignment of your Header and content i.e., you can select where you want to display this Column on your table&#39;s left, right, or center.</p><p><strong>Make row value link to the product:</strong> Click this checkbox if you want to connect the product link to this column as well i.e., if anyone clicks on the ratings it will redirect the customer to the product link in Amazon.</p><p>Once you are done, click the <strong>Add</strong> button and your column will be added to your table.</p><p><img src="'+d+'" alt="Add new table column popup page"></p><p>Here, you can see <strong>a new Reviews column is added</strong> for <strong>showcasing</strong> the <strong>customer ratings</strong> about these products.</p><p><strong>Remember</strong>, once you create the column, you can not change the <strong>Column Type</strong> again. But you can always delete the whole column and create a new one with your desired column type.</p><p>You can anytime <strong>edit</strong> any column by clicking the <strong>Pencil Icon</strong> right next to the column name and <strong>move</strong> the <strong>column</strong> left and right easily by using the <strong>Drag and Drop</strong> button placed just before the column name.</p><p><img src="'+u+'" alt="Reviews column added"></p><p>This way you can add as many columns as you want!</p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',27)])])}const y=t(l,[["render",i]]);export{w as __pageData,y as default};
